final.country_id = staging.country_id,
final.auction_type = staging.auction_type,
final.auction_status = staging.auction_status,
final.make = staging.make,
final.model = staging.model,
final.trim = staging.trim,
final.transmission = staging.transmission,
final.year = staging.year,
